def stringConversion(X, Y):
    # Check if all characters in Y are either uppercase or lowercase
    if not all(c.isupper() or c.islower() for c in Y):
        return 0

    # Initialize a 2D DP table where dp[i][j] will be True if X[:i] can be converted to Y[:j]
    dp = [[False] * (len(Y) + 1) for _ in range(len(X) + 1)]

    # Base case: empty string conversion
    dp[0][0] = True

    # Fill the DP table
    for i in range(1, len(X) + 1):
        for j in range(1, len(Y) + 1):
            # If the characters match (case insensitive) or X's character is uppercase and Y's character is lowercase
            if X[i - 1].lower() == Y[j - 1] or (X[i - 1].islower() and X[i - 1].upper() == Y[j - 1]):
                dp[i][j] = dp[i - 1][j - 1]
            # If X's character is uppercase and we can delete it
            elif X[i - 1].isupper():
                dp[i][j] = False
            # If X's character is lowercase and we can ignore it
            else:
                dp[i][j] = dp[i - 1][j]

    return 1 if dp[len(X)][len(Y)] else 0
